  // BUG D fix: capture mousedown on the WB panel to restore focused-component
  // when Thymer splits caret focus between the WB and the main panel.
  _wbFocusFix = (e) => {
    // TRUSTED user clicks only: our own synthetic pointer sequences (the
    // _hitTestCaret focus helper, e.g. after WB Enter creates a child) must
    // never trigger the settle-check -- at settle time the thread-target can
    // still point at the PREVIOUS caret line in the MAIN panel, and the
    // "fix" would yank the caret there (the post-Enter jump bug).
    if (!e.isTrusted) return;
    // v4.49.7: while a native inline picker (@ date / autocomplete / omni
    // overlay) is open, the click IS the commit. Running the settle-check then
    // yanks the caret to the main panel mid-commit and the picker closes
    // without inserting anything (the "@today does nothing" bug).
    if (this._nativeInlinePickerVisible()) return;
    // Only clicks inside a WB transclusion body (not headers/buttons/cards).
    if (!e.target || !e.target.closest) return;
    if (this._isNativePickerNode(e.target, true)) return;
    if (!e.target.closest(".editor-panel.refx-wb-live")) return;
    if (e.target.closest(".refx-wb-hdr, .refx-propcard, .refx-wb-filterbar, .refx-wb-vmenu, .refx-wb-tabs, .refx-wb-trail, .refx-wb-related, .refx-wb-shared")) return;
    if (!e.target.closest(".transclusion-container-div")) return;
    // After the click settles, check for the split-focus state: WB has
    // focused-component but the caret (flowythymer-thread-target) is in a
    // different panel. Re-fire a trusted pointer sequence on the thread-target's
    // text to restore focused-component to the panel that actually owns the caret.
    setTimeout(() => {
      try {
        // Programmatic-focus suppress window (set by _wbCreateSiblingBelow):
        // while our own focus placement is settling, do not "correct" anything.
        if (performance.now() < (this._wbFocusSuppressUntil || 0)) return;
        const wbEl = document.querySelector(".editor-panel.refx-wb-live");
        if (!wbEl || !wbEl.classList.contains("focused-component")) return;
        const thread = document.querySelector(".flowythymer-thread-target");
        if (!thread) return;
        if (thread.closest(".editor-panel.refx-wb-live")) return; // caret is in WB - no split
        const lineText = thread.querySelector(".lineitem-text") || thread;
        this._hitTestCaret(lineText);
      } catch (_) {}
    }, 0);
  };
