    if (renderResults) nav.selectionRevision = (nav.selectionRevision || 0) + 1;
    nav.selectedGuid = nav.results[nav.selectedIndex]?.guid || null;
    nav.selectionActivatedGuid = nav.selectedGuid;
    nav.revealWindowStart = 0;
    nav.revealWindowEnd = Math.max(nav.visibleLimit || 0, nav.selectedIndex + 1);
    nav.context = null; nav.mediaTargetItem = null; nav.referencesExpanded = false; nav.galleryExpanded = false;
    nav.contextGeneration++;
