      lineGuid,
      pageGuid,
      queryLineGuid,
      queryHostGuid,
      segIndex: span && typeof span.segment_index === "number" ? span.segment_index : null,
      linespanType: span ? span.type : null,
      anchorNode: span ? span.$node : null,
